import { render } from "./engine.ts";

const [templateFile, dataFile] = Bun.argv.slice(2);

if (!templateFile || !dataFile || Bun.argv.slice(2).length !== 2) {
  console.error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  process.exitCode = 1;
} else {
  try {
    const [template, json] = await Promise.all([Bun.file(templateFile).text(), Bun.file(dataFile).text()]);
    process.stdout.write(render(template, JSON.parse(json)));
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}

type Location = { offset: number; line: number; column: number };

type TextNode = { kind: "text"; value: string };
type ValueNode = { kind: "value"; path: string; escaped: boolean; location: Location };
type BlockNode = {
  kind: "block";
  name: "if" | "each";
  path: string;
  body: Node[];
  alternate: Node[] | null;
  location: Location;
};
type Node = TextNode | ValueNode | BlockNode;

type Context = { root: unknown; current: unknown; index?: number };

function locationAt(source: string, offset: number): Location {
  let line = 1;
  let lastNewline = -1;
  for (let i = 0; i < offset; i++) {
    if (source[i] === "\n") {
      line++;
      lastNewline = i;
    }
  }
  return { offset, line, column: offset - lastNewline };
}

function errorAt(source: string, offset: number, message: string): Error {
  const { line, column } = locationAt(source, offset);
  return new Error(`${message} at line ${line}, column ${column}`);
}

function validPath(path: string): boolean {
