  expect(render("{{#if a}}A{{#if b}}B{{else}}C{{/if}}{{else}}D{{/if}}", { a: true, b: 0 })).toBe("AC");
  expect(render("{{#if items}}yes{{else}}no{{/if}}", { items: [] })).toBe("no");
});

